parameters.jsCode:
// Extract sender + build an idempotent inbound interaction insert.
function q(s){ return String(s==null?'':s).replace(/'/g, "''"); }
const email = $('New Email (IMAP)').item.json;
let from = '';
if (email.from && email.from.value && email.from.value[0]) from = email.from.value[0].address;
else if (typeof email.from === 'string') { const m = email.from.match(/<([^>]+)>/); from = m ? m[1] : email.from; }
const subject = email.subject || '';
const text = email.textPlain || email.text || email.textHtml || '';
const mid = email.messageId || email.metadata?.['message-id'] || ('imap-' + Date.now());
let c = {}; const cr = $('Classify Reply').item.json.response || '';
try { c = JSON.parse(cr); } catch(e) { const m = cr.match(/\{[\s\S]*\}/); if (m) { try { c = JSON.parse(m[0]); } catch(_){} } }
const query = `INSERT INTO app.interactions (recruiter_id, direction, channel, message_id, subject, body, summary, classification, sentiment, suggested_reply) VALUES ((SELECT id FROM app.recruiters WHERE email = '${q(from)}' LIMIT 1), 'inbound', 'email', '${q(mid)}', '${q(subject)}', '${q(text.slice(0,8000))}', '${q(c.summary)}', '${q(c.classification || 'other')}', '${q(c.sentiment || 'neutral')}', '${q(c.suggested_reply)}') ON CONFLICT (message_id) DO NOTHING;`;
return [{ json: { query, from, subject, classification: c.classification || 'other', summary: c.summary || '', suggested_reply: c.suggested_reply || '' } }];

